// worktrees: the pi model hosts worktrees manages (Settings → pi → Models).
// Generated by worktrees and rewritten when it differs: do not edit. Loaded
// with `-e` by every pi worktrees starts, never by a pi you start yourself.
//
// It reads ONE file, once, at load, and registers the hosts in it. It never
// throws, never prints for a missing file (a fresh install has none), and
// does nothing on a pi without `registerProvider` (before 0.50.0).
//
// The file is worktrees' own schema, not pi's: no host in it carries a key.
// A host worktrees added gets its own id as a placeholder key, because pi
// lists no provider without one; an `override` of a host pi's models.json
// declares gets none, so pi resolves that host's key as it always does.
import { readFileSync } from "node:fs";

const DATA = __DATA__;

function warn(msg) {
  try { console.error(`worktrees models: ${msg}`); } catch { /* nothing */ }
}

const count = (v, dflt) => (Number.isInteger(v) && v > 0 ? v : dflt);

// pi applies models.json's defaults to models.json, and NONE to
// registerProvider: a model without maxTokens crashes `pi --list-models`
// (1.5.0, formatTokenCount). Every field pi reads is filled here.
function model(m) {
  return {
    id: m.id,
    name: typeof m.name === "string" && m.name ? m.name : m.id,
    reasoning: m.reasoning === true,
    input: m.images === true ? ["text", "image"] : ["text"],
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: count(m.contextWindow, 128000),
    maxTokens: count(m.maxTokens, 16384),
  };
}

export default function worktreesModels(pi) {
  try {
    if (!pi || typeof pi.registerProvider !== "function") return;
    let text;
    try {
      text = readFileSync(DATA, "utf8");
    } catch (e) {
      if (!e || e.code !== "ENOENT") warn(`cannot read ${DATA} (${(e && e.code) || e})`);
      return;
    }
    let data;
    try {
      data = JSON.parse(text);
    } catch {
      warn(`${DATA} is not valid JSON; its hosts are left out`);
      return;
    }
    const hosts = data && typeof data.hosts === "object" && !Array.isArray(data.hosts) ? data.hosts : {};
    for (const [id, h] of Object.entries(hosts)) {
      try {
        if (!h || typeof h.baseUrl !== "string" || !/^https?:\/\//.test(h.baseUrl)) {
          warn(`host ${id}: no http(s) baseUrl; left out`);
          continue;
        }
        const models = (Array.isArray(h.models) ? h.models : [])
          .filter((m) => m && typeof m.id === "string" && m.id)
          .map(model);
        if (models.length === 0) {
          warn(`host ${id}: no models; left out`);
          continue;
        }
        const p = { baseUrl: h.baseUrl, api: typeof h.api === "string" && h.api ? h.api : "openai-completions", models };
        if (h.override !== true) p.apiKey = id;
        pi.registerProvider(id, p);
      } catch (e) {
        warn(`host ${id}: ${(e && e.message) || e}`);
      }
    }
  } catch (e) {
    warn(String((e && e.message) || e));
  }
}
